<?php
include('../auth/check.php');
include('../config/db.php');

$queue_id = intval($_GET['queue_id'] ?? 0);
if ($queue_id <= 0) { header('Location: assessment_screen.php'); exit; }

$stmt = $conn->prepare("SELECT q.id AS queue_id,q.queue_number,q.workflow_status,q.beneficiary_id,b.beneficiary_code,b.first_name,b.middle_name,b.last_name,b.ext_name,b.contact_number,b.birthday_month,b.birthday_day,b.birthday_year,b.age,b.sex,b.region,b.province,b.city_municipality,b.barangay,b.lgu,b.national_id,b.household_id,b.program_type,b.sms_opt_in,b.is_pregnant FROM queue_entries q INNER JOIN beneficiaries b ON b.id=q.beneficiary_id WHERE q.id=? LIMIT 1");
$stmt->bind_param('i',$queue_id);
$stmt->execute();
$data = $stmt->get_result()->fetch_assoc();
if (!$data) { header('Location: assessment_screen.php'); exit; }

$stmt = $conn->prepare("SELECT * FROM eligibility_forms WHERE queue_entry_id=? OR beneficiary_id=? ORDER BY id DESC LIMIT 1");
$stmt->bind_param('ii',$queue_id,$data['beneficiary_id']);
$stmt->execute();
$form = $stmt->get_result()->fetch_assoc() ?: [];

function h($v){return htmlspecialchars($v ?? '',ENT_QUOTES,'UTF-8');}
function s($f,$k,$v){return (strval($f[$k] ?? '')===strval($v))?'selected':'';}
$is_locked = intval($form['form_locked'] ?? 0) === 1;
$name = trim($data['last_name'].', '.$data['first_name'].' '.$data['middle_name'].' '.$data['ext_name']);
$birthday = intval($data['birthday_month']).'/'.intval($data['birthday_day']).'/'.intval($data['birthday_year']);
$isPwd = intval($data['sms_opt_in'] ?? 0) === 1;
$isPregnant = intval($data['is_pregnant'] ?? 0) === 1;
$isSenior = intval($data['age'] ?? 0) >= 60;
$priorityText = $isPwd ? 'PWD Priority' : ($isPregnant ? 'Pregnant Priority' : ($isSenior ? 'Senior Priority' : 'Regular'));
$completeAddress = trim(($data['barangay'] ?? '').', '.($data['city_municipality'] ?? '').', '.($data['province'] ?? '').', '.($data['region'] ?? ''), ', ');
?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Assessment Form</title><link href="https://fonts.googleapis.com/icon?family=Material+Icons" rel="stylesheet"><link rel="stylesheet" href="../assets/style.css"><style>
body{background:#f3f6fb}.wrap{padding:20px;flex:1;overflow:auto}.card{background:white;border:1px solid #d6dce8;border-radius:14px;padding:20px;margin-bottom:16px}h1{margin:0;color:#111827}.muted{color:#6b7280;margin:7px 0 0}.info{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:16px}.info div{background:#f8fafc;border:1px solid #e5e7eb;border-radius:10px;padding:12px}.info span{display:block;color:#64748b;font-size:11px;font-weight:900;text-transform:uppercase;margin-bottom:4px}.info strong{color:#111827;word-break:break-word}.wide{grid-column:span 2}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.field{display:flex;flex-direction:column}.field label{font-size:13px;font-weight:900;color:#374151;margin-bottom:6px}input,select,textarea{min-height:44px;padding:10px 12px;border:1px solid #cbd5e1;border-radius:9px;font-size:14px;background:white}textarea{min-height:78px;resize:vertical}.full{grid-column:1/-1}.actions{display:flex;gap:10px;margin-top:18px;flex-wrap:wrap}.btn{border:0;text-decoration:none;padding:12px 18px;border-radius:9px;font-weight:900;cursor:pointer}.save{background:#2563eb;color:white}.approve{background:#16a34a;color:white}.back{background:#374151;color:white}.lock{display:inline-block;padding:8px 12px;border-radius:999px;font-weight:900;margin-top:12px}.locked{background:#dcfce7;color:#166534}.draft{background:#fef3c7;color:#92400e}.priority{background:#fff7ed!important;border-color:#fed7aa!important;color:#9a3412!important}@media(max-width:900px){.grid,.info{grid-template-columns:1fr}.wide{grid-column:span 1}}
