<div class="card"><h1>GIS / Assessment Form</h1><p class="muted">Beneficiary details below are pulled exactly from the beneficiary record.</p><div class="lock <?php echo $is_locked?'locked':'draft'; ?>"><?php echo $is_locked?'Approved and Locked':'Draft / Not yet approved'; ?></div>
<div class="info">
<div><span>Queue</span><strong><?php echo h($data['queue_number']); ?></strong></div><div><span>Beneficiary Code</span><strong><?php echo h($data['beneficiary_code']); ?></strong></div><div class="wide"><span>Client Name</span><strong><?php echo h($name); ?></strong></div>
<div><span>Birthday</span><strong><?php echo h($birthday); ?></strong></div><div><span>Age / Sex</span><strong><?php echo intval($data['age']); ?> / <?php echo h($data['sex']); ?></strong></div><div><span>Contact Number</span><strong><?php echo h($data['contact_number'] ?: '-'); ?></strong></div><div class="<?php echo ($isPwd||$isPregnant||$isSenior)?'priority':''; ?>"><span>Priority Status</span><strong><?php echo h($priorityText); ?></strong></div>
