<div><span>Program / Assistance</span><strong><?php echo h($data['program_type'] ?: '-'); ?></strong></div><div><span>Region</span><strong><?php echo h($data['region']); ?></strong></div><div><span>Province</span><strong><?php echo h($data['province']); ?></strong></div><div><span>City / Municipality</span><strong><?php echo h($data['city_municipality']); ?></strong></div><div class="wide"><span>Complete Address</span><strong><?php echo h($completeAddress); ?></strong></div>
</div></div>
<form class="card" method="POST" action="../api/save_eligibility.php">
<input type="hidden" name="queue_id" value="<?php echo intval($queue_id); ?>"><input type="hidden" name="beneficiary_id" value="<?php echo intval($data['beneficiary_id']); ?>">
<div class="grid">
<div class="field"><label>ID / Requirement Presented</label><select name="id_type_presented" <?php echo $is_locked?'disabled':''; ?> required><option value="">Select</option><option value="Government ID" <?php echo s($form,'id_type_presented','Government ID'); ?>>National/Government ID</option><option value="Barangay Certificate" <?php echo s($form,'id_type_presented','Barangay Certificate'); ?>>Barangay Certificate</option><option value="Senior Citizen ID" <?php echo s($form,'id_type_presented','Senior Citizen ID'); ?>>Senior Citizen ID</option><option value="PWD ID" <?php echo s($form,'id_type_presented','PWD ID'); ?>>PWD ID</option><option value="No Valid ID" <?php echo s($form,'id_type_presented','No Valid ID'); ?>>No Valid ID</option></select></div>
<div class="field"><label>Masterlist Match</label><select name="matches_masterlist" <?php echo $is_locked?'disabled':''; ?> required><option value="Yes" <?php echo s($form,'matches_masterlist','Yes'); ?>>Yes</option><option value="No" <?php echo s($form,'matches_masterlist','No'); ?>>No</option></select></div>
<div class="field"><label>Beneficiary Type</label><select name="beneficiary_type" <?php echo $is_locked?'disabled':''; ?> required><option value="">Select</option><option value="Indigent" <?php echo s($form,'beneficiary_type','Indigent'); ?>>Indigent</option><option value="Senior Citizen" <?php echo s($form,'beneficiary_type','Senior Citizen'); ?>>Senior Citizen</option><option value="PWD" <?php echo s($form,'beneficiary_type','PWD'); ?>>PWD</option><option value="Pregnant" <?php echo s($form,'beneficiary_type','Pregnant'); ?>>Pregnant</option><option value="Solo Parent" <?php echo s($form,'beneficiary_type','Solo Parent'); ?>>Solo Parent</option><option value="Medical Assistance" <?php echo s($form,'beneficiary_type','Medical Assistance'); ?>>Medical Assistance</option><option value="Educational Assistance" <?php echo s($form,'beneficiary_type','Educational Assistance'); ?>>Educational Assistance</option></select></div>
<div class="field"><label>Source of Income</label><select name="income_source" <?php echo $is_locked?'disabled':''; ?> required><option value="">Select</option><option value="BSNS" <?php echo s($form,'income_source','BSNS'); ?>>BSNS - Business</option><option value="SLRY" <?php echo s($form,'income_source','SLRY'); ?>>SLRY - Salary</option><option value="NONE" <?php echo s($form,'income_source','NONE'); ?>>None</option></select></div>
<div class="field"><label>Household Members</label><select name="household_members" <?php echo $is_locked?'disabled':''; ?> required><option value="">Select</option><?php for($i=1;$i<=10;$i++): ?><option value="<?php echo $i; ?>" <?php echo s($form,'household_members',$i); ?>><?php echo $i; ?></option><?php endfor; ?><option value="11" <?php echo s($form,'household_members','11'); ?>>11+</option></select></div>
<div class="field"><label>Dependents</label><select name="dependents" <?php echo $is_locked?'disabled':''; ?> required><option value="">Select</option><?php for($i=0;$i<=8;$i++): ?><option value="<?php echo $i; ?>" <?php echo s($form,'dependents',$i); ?>><?php echo $i; ?></option><?php endfor; ?><option value="9" <?php echo s($form,'dependents','9'); ?>>9+</option></select></div>
<div class="field"><label>Requirement Status</label><select name="supporting_documents" <?php echo $is_locked?'disabled':''; ?> required><option value="Complete" <?php echo s($form,'supporting_documents','Complete'); ?>>Complete</option><option value="Incomplete" <?php echo s($form,'supporting_documents','Incomplete'); ?>>Incomplete</option><option value="For Verification" <?php echo s($form,'supporting_documents','For Verification'); ?>>For Verification</option></select></div>
<div class="field"><label>Eligibility Status</label><select name="eligibility_status" <?php echo $is_locked?'disabled':''; ?> required><option value="Pending Review" <?php echo s($form,'eligibility_status','Pending Review'); ?>>Pending Review</option><option value="Eligible" <?php echo s($form,'eligibility_status','Eligible'); ?>>Eligible</option><option value="Not Eligible" <?php echo s($form,'eligibility_status','Not Eligible'); ?>>Not Eligible</option></select></div>
<div class="field"><label>Approved Amount</label><select name="approved_cash_amount" <?php echo $is_locked?'disabled':''; ?> required><option value="">Select</option><?php foreach([1000,2000,3000,5000] as $amt): ?><option value="<?php echo $amt; ?>" <?php echo floatval($form['approved_cash_amount'] ?? 0)==$amt?'selected':''; ?>>₱<?php echo number_format($amt); ?></option><?php endforeach; ?></select></div>
<div class="field full"><label>Reason / Remarks</label><select name="assistance_reason" <?php echo $is_locked?'disabled':''; ?> required><option value="Financial Assistance" <?php echo s($form,'assistance_reason','Financial Assistance'); ?>>Financial Assistance</option><option value="Medical Assistance" <?php echo s($form,'assistance_reason','Medical Assistance'); ?>>Medical Assistance</option><option value="Educational Assistance" <?php echo s($form,'assistance_reason','Educational Assistance'); ?>>Educational Assistance</option><option value="Emergency Assistance" <?php echo s($form,'assistance_reason','Emergency Assistance'); ?>>Emergency Assistance</option></select></div>
